01.2000 - 31.12.2050","sport":"Snowboard","status":"draft"},{"amount":"860.00","day_count":1,"duration_minutes":360,"family":"Privatkurs","group_capacity":4,"persons":4,"product_key":"private:snowboard","source_activities":"Snowboard Anfänger | Snowboard Fortgeschritten","source_description":"Snowboard, 1 T, 360 m, 4 Teiln., max 4","source_id":"23645","source_row":64,"source_validity":"01.01.2000 - 31.12.2050","sport":"Snowboard","status":"draft"},{"amount":"980.00","day_count":1,"duration_minutes":360,"family":"Privatkurs","group_capacity":5,"persons":5,"product_key":"private:snowboard","source_activities":"Snowboard Anfänger | Snowboard Fortgeschritten","source_description":"Snowboard, 1 T, 360 m, 5 Teiln., max 5","source_id":"23646","source_row":65,"source_validity":"01.01.2000 - 31.12.2050","sport":"Snowboard","status":"draft"},{"amount":"585.00","day_count":1,"duration_minutes":420,"family":"Privatkurs","group_capacity":1,"persons":1,"product_key":"private:snowboard","source_activities":"Snowboard Anfänger | Snowboard Fortgeschritten","source_description":"Snowboard, 1 T, 420 m, 1 Teiln., max 1","source_id":"23654","source_row":66,"source_validity":"01.01.2000 - 31.12.2050","sport":"Snowboard","status":"draft"},{"amount":"725.00","day_count":1,"duration_minutes":420,"family":"Privatkurs","group_capacity":2,"persons":2,"product_key":"private:snowboard","source_activities":"Snowboard Anfänger | Snowboard Fortgeschritten","source_description":"Snowboard, 1 T, 420 m, 2 Teiln., max 2","source_id":"23655","source_row":67,"source_validity":"01.01.2000 - 31.12.2050","sport":"Snowboard","status":"draft"},{"amount":"865.00","day_count":1,"duration_minutes":420,"family":"Privatkurs","group_capacity":3,"persons":3,"product_key":"private:snowboard","source_activities":"Snowboard Anfänger | Snowboard Fortgeschritten","source_description":"Snowboard, 1 T, 420 m, 3 Teiln., max 3","source_id":"23656","source_row":68,"source_validity":"01.01.2000 - 31.12.2050","sport":"Snowboard","status":"draft"},{"amount":"1005.00","day_count":1,"duration_minutes":420,"family":"Privatkurs","group_capacity":4,"persons":4,"product_key":"private:snowboard","source_activities":"Snowboard Anfänger | Snowboard Fortgeschritten","source_description":"Snowboard, 1 T, 420 m, 4 Teiln., max 4","source_id":"23657","source_row":69,"source_validity":"01.01.2000 - 31.12.2050","sport":"Snowboard","status":"draft"},{"amount":"1145.00","day_count":1,"duration_minutes":420,"family":"Privatkurs","group_capacity":5,"persons":5,"product_key":"private:snowboard","source_activities":"Snowboard Anfänger | Snowboard Fortgeschritten","source_description":"Snowboard, 1 T, 420 m, 5 Teiln., max 5","source_id":"23658","source_row":70,"source_validity":"01.01.2000 - 31.12.2050","sport":"Snowboard","status":"draft"}]}$bc_json$::jsonb;
  v_sha text := 'b5db33ab54a9c9565edd6541461a3b982afc4a5f78ded6bbd833e99ee3f14d67';
  v_season uuid;
  v_count integer;
BEGIN
  SELECT id INTO STRICT v_season FROM public.seasons WHERE name='Winter 26/27'
    AND start_date=DATE '2026-12-01' AND end_date=DATE '2027-04-15' AND is_current IS TRUE;
  IF jsonb_array_length(v_payload->'products') <> 15 OR jsonb_array_length(v_payload->'tariffs') <> 121 THEN
    RAISE EXCEPTION 'Embedded product/source row count drift';
  END IF;
  IF (SELECT count(DISTINCT rowdata->>'source_id') FROM jsonb_array_elements(v_payload->'tariffs') rowdata) <> 121
     OR (SELECT count(*) FROM jsonb_array_elements(v_payload->'tariffs') rowdata
         WHERE rowdata->>'status' = 'deferred_care') <> 6 THEN
    RAISE EXCEPTION 'Source identity/care classification drift';
  END IF;

  INSERT INTO public.products
    (id,season_id,name,description,type,duration_minutes,price,currency,vat_rate,
     is_active,sort_order,pricing_type,is_training_product,discipline,audience,reporting_category)
  SELECT (p->>'product_id')::uuid, v_season, p->>'name', p->>'description', p->>'type',
         (p->>'duration_minutes')::integer,(p->>'price')::numeric,'CHF',7.7,
         false,200+(row_number() OVER (ORDER BY p->>'product_key'))::integer,
         p->>'pricing_type', false,p->>'discipline',p->>'audience',p->>'reporting_category'
  FROM jsonb_array_elements(v_payload->'products') p;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  IF v_count <> 15 THEN RAISE EXCEPTION 'Expected 15 inactive products, got %',v_count; END IF;

  INSERT INTO public.bc_product_tariff_sources
    (source_id,season_id,product_id,source_sha256,source_family,import_status,
     day_count,duration_minutes,persons_per_lesson,price_chf,source_payload)
  SELECT r->>'source_id',v_season,(m.product_record->>'product_id')::uuid,v_sha,
         r->>'family',r->>'status',(r->>'day_count')::int,(r->>'duration_minutes')::int,
         (r->>'persons')::int,(r->>'amount')::numeric,r
  FROM jsonb_array_elements(v_payload->'tariffs') r
  LEFT JOIN LATERAL (
    SELECT p AS product_record FROM jsonb_array_elements(v_payload->'products') p
    WHERE p->>'product_key'=r->>'product_key' LIMIT 1
  ) m ON true;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  IF v_count <> 121 THEN RAISE EXCEPTION 'Expected 121 source tariffs, got %',v_count; END IF;

  -- Existing YETI product_price_tiers are cumulative group day prices.
  -- Only source-present day counts are added. Missing day counts stay absent.
  INSERT INTO public.product_price_tiers(product_id,day_count,cumulative_price)
  SELECT s.product_id,s.day_count,s.price_chf FROM public.bc_product_tariff_sources s
  WHERE s.import_status='draft' AND s.source_family IN ('Gruppenunterricht','Samstagkurs');
  GET DIAGNOSTICS v_count = ROW_COUNT;
  IF v_count <> 45 THEN RAISE EXCEPTION 'Expected 45 verified group day tiers, got %',v_count; END IF;

  IF (SELECT count(*) FROM public.products WHERE season_id=v_season AND is_active IS FALSE) <> 15
      OR (SELECT count(*) FROM public.products WHERE is_active IS TRUE) <> 15
      OR (SELECT count(*) FROM public.product_price_tiers) <> 58
      OR (SELECT count(*) FROM public.bc_product_tariff_sources WHERE import_status='draft' AND source_family='Privatkurs') <> 70
      OR (SELECT count(*) FROM public.bc_product_tariff_sources WHERE import_status='deferred_care') <> 6
      OR (SELECT count(*) FROM public.products WHERE season_id=v_season AND currency='CHF') <> 15
      OR (SELECT count(*) FROM public.bc_product_tariff_sources WHERE source_sha256=v_sha) <> 121 THEN
    RAISE EXCEPTION 'Postflight mismatch: roll back the product draft transaction';
  END IF;
  RAISE NOTICE 'Imported 15 inactive 26/27 product drafts, 45 verified group tiers, 70 private price points, 6 deferred care tariffs';
END;
$apply$;

DO $activation_test$ BEGIN
  BEGIN
    UPDATE public.products SET is_active=true WHERE id=(SELECT product_id FROM public.bc_product_tariff_sources WHERE source_family='Privatkurs' LIMIT 1);
    RAISE EXCEPTION 'activation unexpectedly succeeded';
  EXCEPTION WHEN raise_exception THEN
    IF SQLERRM <> 'Booking-Corner draft cannot be activated before pricing release gate' THEN RAISE; END IF;
  END;
END; $activation_test$;

SELECT (SELECT count(*) FROM public.products WHERE season_id=(SELECT id FROM public.seasons WHERE name='Winter 26/27') AND is_active IS FALSE) AS draft_products,
       (SELECT count(*) FROM public.product_price_tiers WHERE product_id IN (SELECT id FROM public.products WHERE season_id=(SELECT id FROM public.seasons WHERE name='Winter 26/27'))) AS imported_group_tiers,
       (SELECT count(*) FROM public.bc_product_tariff_sources WHERE source_family='Privatkurs') AS private_rate_rows,
       (SELECT count(*) FROM public.bc_product_tariff_sources WHERE import_status='deferred_care') AS care_review_rows,
       (SELECT count(*) FROM public.products WHERE is_active IS TRUE) AS old_active_products;
ROLLBACK;
